mapper.select:
SELECT * FROM agent_task_log
WHERE 1=1

    AND task_id = #{taskId}


    AND task_name LIKE CONCAT('%', #{taskName}, '%')


    AND status = #{status}


    AND start_time >= #{startTimeFrom}


    AND start_time <= #{startTimeTo}


    AND (prompt LIKE CONCAT('%', #{keyword}, '%')
         OR response LIKE CONCAT('%', #{keyword}, '%')
         OR error_info LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY create_time DESC
